<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php'; require_login(); require_once __DIR__.'/../config/database.php'; verify_csrf();
$tipo=strtoupper($_GET['tipo']??$_POST['tipo']??''); if(!in_array($tipo,['INGRESO','EGRESO'],true))$tipo='';
$mensaje='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $accion=$_POST['accion']??'';
 if($accion==='crear'){
  require_role(['administrador','tesorero']);
  $tp=strtoupper($_POST['tipo']??'');$fecha=$_POST['fecha']??'';$concepto=trim($_POST['concepto']??'');$ref=trim($_POST['referencia']??'');$monto=filter_var($_POST['monto']??null,FILTER_VALIDATE_FLOAT);
  if(!in_array($tp,['INGRESO','EGRESO'],true)||!$concepto||$monto===false||$monto<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$fecha))$error='Verifica tipo, fecha, concepto y monto.';
  else{$s=$pdo->prepare("INSERT INTO movimientos(tipo,fecha,concepto,referencia,monto,estado,usuario_id) VALUES(?,?,?,?,?,'PENDIENTE',?)");$s->execute([$tp,$fecha,$concepto,$ref,$monto,$_SESSION['usuario']['id']]);$id=(int)$pdo->lastInsertId();audit($pdo,'REGISTRAR','movimientos',$id,"$tp S/ $monto");$mensaje='Movimiento registrado como pendiente.';$tipo=$tp;}
 } elseif($accion==='confirmar'){
  require_role(['administrador','tesorero']);$id=(int)($_POST['id']??0);
  $s=$pdo->prepare("UPDATE movimientos SET estado='CONFIRMADO',confirmado_por=?,confirmado_en=NOW() WHERE id=? AND estado='PENDIENTE'");$s->execute([$_SESSION['usuario']['id'],$id]);
  if($s->rowCount()){audit($pdo,'CONFIRMAR','movimientos',$id,'Movimiento confirmado');$mensaje='Movimiento confirmado.';}else $error='No se pudo confirmar: verifica que siga pendiente.';
 } elseif($accion==='anular'){
  require_role(['administrador']);$id=(int)($_POST['id']??0);$mot=trim($_POST['motivo']??'');
  if($mot==='')$error='Indica el motivo de anulación.';else{$s=$pdo->prepare("UPDATE movimientos SET estado='ANULADO',motivo_anulacion=? WHERE id=? AND estado<>'ANULADO'");$s->execute([$mot,$id]);if($s->rowCount()){audit($pdo,'ANULAR','movimientos',$id,$mot);$mensaje='Movimiento anulado con trazabilidad.';}else$error='No se pudo anular el movimiento.';}
 }
}
$rows=$pdo->query("SELECT m.*,u.nombre responsable FROM movimientos m JOIN usuarios u ON u.id=m.usuario_id ORDER BY m.fecha DESC,m.id DESC")->fetchAll();
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movimientos | Tesorería</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><aside class="sidebar"><div class="brand"><img src="../assets/img/logo_iestp.png"><div><strong>IESTP UTCUBAMBA</strong><small>Tesorería · 2026</small></div></div><nav><a href="../index.php">▦ Dashboard</a><a class="active" href="movimientos.php">⇄ Movimientos</a><a href="comprobantes.php">▤ Comprobantes</a><a href="usuarios.php">♙ Usuarios</a></nav><div class="sidebar-bottom"><a href="../logout.php">↪ Cerrar sesión</a></div></aside><main class="main"><header class="topbar"><div><span class="eyebrow">OPERACIONES FINANCIERAS</span><h1>Ingresos y egresos</h1><p>Registro, revisión y confirmación de operaciones.</p></div><a class="btn btn-light" href="../index.php">Dashboard</a></header>
<?php if($mensaje):?><p class="notice"><?=e($mensaje)?></p><?php endif;?><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?>
<?php if(in_array($_SESSION['usuario']['rol'],['administrador','tesorero'],true)):?><section class="panel"><h3>Registrar movimiento</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="crear"><div><label>Tipo</label><select name="tipo" required><option value="">Seleccione</option><option value="INGRESO" <?=$tipo==='INGRESO'?'selected':''?>>Ingreso</option><option value="EGRESO" <?=$tipo==='EGRESO'?'selected':''?>>Egreso</option></select></div><div><label>Fecha</label><input type="date" name="fecha" value="<?=date('Y-m-d')?>" required></div><div class="wide"><label>Concepto / descripción</label><input name="concepto" maxlength="250" required></div><div><label>Referencia o documento</label><input name="referencia" maxlength="100"></div><div><label>Monto (S/)</label><input type="number" name="monto" min="0.01" step="0.01" required></div><div class="wide"><button class="btn">Guardar como pendiente</button></div></form></section><?php endif;?>
<section class="panel"><h3>Movimientos registrados</h3><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Concepto</th><th>Referencia</th><th>Monto</th><th>Estado</th><th>Responsable</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['tipo'])?></td><td><?=e($r['concepto'])?></td><td><?=e($r['referencia'])?></td><td>S/ <?=number_format((float)$r['monto'],2)?></td><td><span class="tag"><?=e($r['estado'])?></span></td><td><?=e($r['responsable'])?></td><td><?php if($r['estado']==='PENDIENTE'&&in_array($_SESSION['usuario']['rol'],['administrador','tesorero'],true)):?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="confirmar"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small">Confirmar</button></form><?php endif;?><?php if($r['estado']!=='ANULADO'&&$_SESSION['usuario']['rol']==='administrador'):?><form method="post" class="inline-form" onsubmit="return confirm('¿Anular este movimiento?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="accion" value="anular"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="motivo" placeholder="Motivo obligatorio" required><button class="btn btn-danger btn-small">Anular</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8">Aún no hay movimientos registrados.</td></tr><?php endif;?></tbody></table></div></section><footer>Solo los movimientos confirmados afectan el saldo del dashboard.</footer></main></div></body></html>